	for rows.Next() {
		var i ListThreadsRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.DealerID,
			&i.GroupID,
			&i.ContactID,
			&i.WaJid,
			&i.Title,
			&i.Subtitle,
			&i.SalesID,
			&i.LastMessageAt,
			&i.Unread,
			&i.Identification,
			&i.Tag,
			&i.Suggestions,
			&i.SeedKey,
			&i.Account,
			&i.HistoryReqOldest,
			&i.HistoryReqAt,
			&i.HistoryTries,
			&i.HistoryDoneAt,
			&i.DealerSlug,
			&i.DealerName,
			&i.SalesName,
			&i.GroupKind,
			&i.AccountLabel,
			&i.LastBody,
			&i.LastFrom,
			&i.LastDirection,
			&i.WaitingSince,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
